import Header from '../components/Header';
import Footer from '../components/Footer';
import '../styles/home.css';

function Detail() {
    return (
    <div className="home">
        
        <Header />

        <div className="container">
            <div className="article-container">
                <h1>Détail du produit</h1>
            </div>
        </div>
        
        <Footer />

    </div>
        
    );
}
export default Detail;
